// Generated by esquadro: do not edit. The file and image fields: a field
// to send one (dragged in or chosen, checked for its size and format
// before it goes, with its progress), and how one is shown (an image, or
// a link to download it).
import { FileIcon, ImagePlus, Loader2, RefreshCw, Trash2, Upload } from "lucide-react"
import { useEffect, useRef, useState } from "react"
import { Button } from "@/components/ui/button"
import { Progress } from "@/components/ui/progress"
import { cn } from "@/lib/utils"
import { api } from "../api.ts"
import { describe } from "./errors.ts"
import { t } from "./i18n.ts"
import type { FieldMeta } from "./meta.ts"

/** A file a record keeps, as the API answers it. */
export interface StoredFile {
  id: string
  name: string
  size: number
  content_type: string
  url: string
}

/** Whether v is a file as the API answers it. */
export function isStoredFile(v: unknown): v is StoredFile {
  return typeof v === "object" && v !== null && typeof (v as StoredFile).id === "string" && "url" in v
}

/** A size as people read it: 4,2 MB. */
export function formatSize(bytes: number): string {
  const units = ["B", "KB", "MB", "GB"]
  let n = bytes
  let i = 0
  while (n >= 1024 && i < units.length - 1) {
    n /= 1024
    i++
  }
  return `${new Intl.NumberFormat(undefined, { maximumFractionDigits: i === 0 ? 0 : 1 }).format(n)} ${units[i]}`
}

/** The formats a field takes, as people read them: PNG, JPEG, WEBP. */
function formatsOf(field: FieldMeta): string {
  return (field.accept ?? []).map((m) => (m.split("/")[1] ?? m).replace(/^.*\./, "").replace("svg+xml", "svg").toUpperCase()).join(", ")
}

type Uploads = { send(input: { entity: string; field: string; file: File; onProgress?: (done: number) => void }): Promise<string> }

/**
 * The field of a file or an image: its value is the file (as the API
 * answers it, or as just sent), and the record is saved with its id.
 */
export function FileInput({
  id,
  field,
  value,
  onChange,
  invalid,
}: {
  id: string
  field: FieldMeta
  value: unknown
  onChange: (v: StoredFile | null) => void
  invalid?: boolean
}) {
  const input = useRef<HTMLInputElement>(null)
  const [progress, setProgress] = useState<number | null>(null)
  const [error, setError] = useState<string>()
  const [over, setOver] = useState(false)
  const file = isStoredFile(value) ? value : null
  const image = field.kind === "image"

  // A preview of a file just chosen lives until it is replaced.
  useEffect(() => {
    const url = file?.url
    return () => {
      if (url?.startsWith("blob:")) URL.revokeObjectURL(url)
    }
  }, [file?.url])

  const send = async (chosen: File) => {
    setError(undefined)
    if (field.maxSize && chosen.size > field.maxSize) {
      setError(t("fileTooLarge", { max: formatSize(field.maxSize) }))
      return
    }
    if (field.accept?.length && !field.accept.includes(chosen.type)) {
      setError(t("fileType", { formats: formatsOf(field) }))
      return
    }
    const uploads = (api as unknown as { uploads?: Uploads }).uploads
    if (!uploads || !field.upload) return
    setProgress(0)
    try {
      const sent = await uploads.send({ ...field.upload, file: chosen, onProgress: setProgress })
      onChange({ id: sent, name: chosen.name, size: chosen.size, content_type: chosen.type, url: URL.createObjectURL(chosen) })
    } catch (e) {
      setError(e instanceof Error && !("status" in e) ? t("uploadFailed") : describe(e))
    } finally {
      setProgress(null)
    }
  }

  const pick = () => input.current?.click()
  const hidden = (
    <input
      ref={input}
      id={id}
      type="file"
      className="sr-only"
      accept={field.accept?.join(",") || (image ? "image/*" : undefined)}
      onChange={(e) => {
        const chosen = e.target.files?.[0]
        e.target.value = ""
        if (chosen) void send(chosen)
      }}
      aria-invalid={invalid}
    />
  )

  if (progress !== null) {
    return (
      <div className="flex flex-col gap-2 rounded-xl border border-border p-4" aria-live="polite">
        <div className="flex items-center gap-2 text-sm font-semibold">
          <Loader2 className="size-4 animate-spin text-primary" /> {t("uploading", { pct: Math.round(progress * 100) })}
        </div>
        <Progress value={progress * 100} />
      </div>
    )
  }

  if (file) {
    // Side by side where there is room; one under the other in a narrow
    // card.
    return (
      <div className="@container rounded-xl border border-border p-3">
        <div className="flex flex-col gap-3 @md:flex-row @md:items-center @md:gap-4">
        {hidden}
        {image ? (
          <img src={file.url} alt="" className="aspect-square w-full max-w-48 shrink-0 rounded-lg border border-border object-cover @md:size-20" />
        ) : (
          <div className="flex size-12 shrink-0 items-center justify-center rounded-lg bg-muted text-muted-foreground">
            <FileIcon className="size-5" />
          </div>
        )}
        <div className="min-w-0 flex-1">
          <p className="truncate font-semibold text-foreground">{file.name}</p>
          <p className="text-xs text-muted-foreground">{formatSize(file.size)}</p>
          {error && <p className="mt-1 text-xs text-destructive">{error}</p>}
        </div>
        <div className="flex shrink-0 gap-1">
          <Button type="button" variant="outline" size="sm" onClick={pick}>
            <RefreshCw /> {t("replaceFile")}
          </Button>
          <Button type="button" variant="ghost" size="sm" className="text-destructive hover:text-destructive" onClick={() => onChange(null)}>
            <Trash2 /> {t("removeFile")}
          </Button>
        </div>
        </div>
      </div>
    )
  }

  const Icon = image ? ImagePlus : Upload
  return (
    <div>
      {hidden}
      <button
        type="button"
        onClick={pick}
        onDragOver={(e) => {
          e.preventDefault()
          setOver(true)
        }}
        onDragLeave={() => setOver(false)}
        onDrop={(e) => {
          e.preventDefault()
          setOver(false)
          const chosen = e.dataTransfer.files?.[0]
          if (chosen) void send(chosen)
        }}
        className={cn(
          "flex w-full flex-col items-center gap-2 rounded-xl border border-dashed border-border bg-input/60 px-4 py-6 text-center transition-colors hover:border-primary hover:bg-primary/5 focus-visible:ring-2 focus-visible:ring-ring focus-visible:outline-none",
          over && "border-primary bg-primary/5",
          invalid && "border-destructive",
        )}
      >
        <Icon className="size-6 text-muted-foreground" />
        <span className="text-sm font-semibold text-foreground">{image ? t("dropImage") : t("dropFile")}</span>
        <span className="text-xs text-muted-foreground">
          {[formatsOf(field), field.maxSize ? t("upTo") + " " + formatSize(field.maxSize) : ""].filter(Boolean).join(" · ")}
        </span>
      </button>
      {error && <p className="mt-1.5 text-xs text-destructive">{error}</p>}
    </div>
  )
}

/** A file as shown: an image, small, or a link to download it with its size. */
export function FileValue({ field, value }: { field: FieldMeta; value: unknown }) {
  if (!isStoredFile(value)) return <span className="text-muted-foreground">—</span>
  if (field.kind === "image") {
    return (
      <a href={value.url} target="_blank" rel="noreferrer" onClick={(e) => e.stopPropagation()}>
        <img src={value.url} alt={value.name} loading="lazy" className="size-10 rounded-lg border border-border object-cover" />
      </a>
    )
  }
  return (
    <a
      href={value.url}
      target="_blank"
      rel="noreferrer"
      onClick={(e) => e.stopPropagation()}
      className="inline-flex max-w-full items-center gap-1.5 font-semibold text-primary underline-offset-4 hover:underline"
    >
      <FileIcon className="size-4 shrink-0" />
      <span className="truncate">{value.name}</span>
      <span className="shrink-0 text-xs font-normal text-muted-foreground">{formatSize(value.size)}</span>
    </a>
  )
}
